import type { ReactNode } from 'react';
import { View } from 'react-native';

import { Text } from '@/components/ui/text';
import { cn } from '@/lib/utils';

/** Grouped, card-style section used in settings/profile lists. */
export function Section({
  title,
  children,
  className,
}: {
  title?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <View className={cn('gap-2', className)}>
      {title ? (
        <Text className="px-1 text-xs uppercase tracking-wide text-muted-foreground">{title}</Text>
      ) : null}
      <View className="overflow-hidden rounded-xl border border-border bg-card">{children}</View>
    </View>
  );
}
